// One fixed source/input value proof experiment. Never a nonce screen.
use super::{Program,QX,QCX,QCCX,QSWAP,QZERO,CINV,CZERO,CONE,CRNG};
use std::collections::HashMap;
#[derive(Default)]struct Aig{nodes:Vec<(u8,u32,u32)>,ands:HashMap<(u32,u32),u32>,xors:HashMap<(u32,u32),u32>}
impl Aig{
 fn node(&mut self,k:u8,a:u32,b:u32)->u32{self.nodes.push((k,a,b));u32::try_from(self.nodes.len()).unwrap()*2}
 fn and(&mut self,mut a:u32,mut b:u32)->u32{if a==0||b==0{return 0;}if a==1{return b;}if b==1||a==b{return a;}if a==b^1{return 0;}for(x,y)in[(a,b),(b,a)]{if x&1==0{let(k,u,v)=self.nodes[(x/2-1)as usize];if k==1{if u==y||v==y{return x;}if u==y^1||v==y^1{return 0;}}}}if a>b{std::mem::swap(&mut a,&mut b);}if let Some(&id)=self.ands.get(&(a,b)){return id;}let id=self.node(1,a,b);self.ands.insert((a,b),id);id}
 fn xor(&mut self,mut a:u32,mut b:u32)->u32{if a==0{return b;}if b==0{return a;}if a==1{return b^1;}if b==1{return a^1;}let neg=(a^b)&1;a&=!1;b&=!1;if a==b{return neg;}for(x,y)in[(a,b),(b,a)]{let(k,u,v)=self.nodes[(x/2-1)as usize];if k==2{if u==y{return v^neg;}if v==y{return u^neg;}}}if a>b{std::mem::swap(&mut a,&mut b);}if let Some(&id)=self.xors.get(&(a,b)){return id^neg;}let id=self.node(2,a,b);self.xors.insert((a,b),id);id^neg}
 fn ite(&mut self,g:u32,a:u32,b:u32)->u32{if g==0||a==b{return b;}if g==1{return a;}if a==b^1{return self.xor(g,b);}if a==0{return self.and(g^1,b);}if b==0{return self.and(g,a);}if a==1{return self.and(g^1,b^1)^1;}if b==1{return self.and(g,a^1)^1;}let x=self.xor(a,b);let y=self.and(g,x);self.xor(b,y)}
 fn evaluate(&self,random:&[u64])->Vec<bool>{let mut values=vec![];let get=|lit:u32,values:&Vec<bool>|if lit<=1{lit==1}else{values[(lit/2-1)as usize]^(lit&1!=0)};for &(k,a,b)in &self.nodes{values.push(match k{0=>random[a as usize]&1!=0,1=>get(a,&values)&get(b,&values),2=>get(a,&values)^get(b,&values),_=>unreachable!()});}values}
}
fn literal_value(lit:u32,values:&[bool])->bool{if lit<=1{lit==1}else{values[(lit/2-1)as usize]^(lit&1!=0)}}
fn construct(p:&Program,initial_q:&[u64],initial_bits:&[u64])->Result<(Aig,Vec<u32>),usize>{let mut aig=Aig::default();let mut q:Vec<_>=initial_q.iter().map(|&v|(v&1)as u32).collect();let mut c=vec![0;p.versions];for(i,&v)in initial_bits.iter().enumerate(){c[i]=(v&1)as u32;}let mut random=HashMap::new();for(i,n)in p.nodes.iter().enumerate(){if aig.nodes.len()>4_000_000{return Err(i);}if i%1000000==0{eprintln!("AIG_PROGRESS source_nodes={i} Boolean_nodes={}",aig.nodes.len());}let mut g=1;for &v in &p.guards[n.g as usize]{g=aig.and(g,c[v as usize]);}let t=n.t as usize;match n.k{QX=>q[t]=aig.xor(q[t],g),QCX=>{let x=aig.and(g,q[n.a as usize]);q[t]=aig.xor(q[t],x);},QCCX=>{let a=aig.and(g,q[n.a as usize]);let x=aig.and(a,q[n.b as usize]);q[t]=aig.xor(q[t],x);},QSWAP=>{let a=n.a as usize;let x=aig.xor(q[a],q[t]);let x=aig.and(g,x);q[a]=aig.xor(q[a],x);q[t]=aig.xor(q[t],x);},QZERO=>q[t]=aig.and(q[t],g^1),CINV=>c[t]=aig.xor(c[n.a as usize],g),CZERO=>c[t]=aig.and(c[n.a as usize],g^1),CONE=>c[t]=aig.and(c[n.a as usize]^1,g^1)^1,CRNG=>{let fresh=*random.entry(n.r).or_insert_with(||aig.node(0,n.r,0));c[t]=aig.ite(g,fresh,c[n.a as usize]);},_=>unreachable!()}}Ok((aig,q))}
fn cnf(aig:&Aig,outputs:&[u32],expected:&[bool])->(String,usize,usize){let mut live=vec![false;aig.nodes.len()];let mut stack=outputs.to_vec();while let Some(lit)=stack.pop(){if lit<=1{continue;}let i=(lit/2-1)as usize;if live[i]{continue;}live[i]=true;let(k,a,b)=aig.nodes[i];if k!=0{stack.push(a);stack.push(b);}}let mut ids=vec![0i64;aig.nodes.len()];let mut count=0;for(i,&yes)in live.iter().enumerate(){if yes{count+=1;ids[i]=count as i64;}}let lit=|v:u32|{assert!(v>1);let id=ids[(v/2-1)as usize];assert!(id>0);if v&1==0{id}else{-id}};let mut clauses=String::new();let mut total=0;let mut put=|xs:&[i64]|{for x in xs{clauses.push_str(&format!("{x} "));}clauses.push_str("0\n");total+=1;};for(i,&yes)in live.iter().enumerate(){if !yes{continue;}let(k,a,b)=aig.nodes[i];if k==0{continue;}let(z,a,b)=(ids[i],lit(a),lit(b));if k==1{put(&[-z,a]);put(&[-z,b]);put(&[z,-a,-b]);}else{put(&[-a,-b,-z]);put(&[a,b,-z]);put(&[a,-b,z]);put(&[-a,b,z]);}}for(&v,&e)in outputs.iter().zip(expected){if v<=1{if (v==1)!=e{put(&[]);}}else{put(&[if e{lit(v)}else{-lit(v)}]);}}(format!("p cnf {count} {total}\n{clauses}"),count,total)}
pub(super)fn audit(p:&Program,ops:&[quantum_ecc::circuit::Op],outputs:&[usize])->serde_json::Value{use quantum_ecc::sim::Simulator;use quantum_ecc::circuit::{analyze_ops,QubitOrBit};let fixtures:Vec<serde_json::Value>=serde_json::from_str(include_str!("FAILURE-FIXTURES.json")).unwrap();let fixture=&fixtures[0];let curve=super::audit_curve();let k1=fixture["k1"].as_str().unwrap().parse().unwrap();let k2=fixture["k2"].as_str().unwrap().parse().unwrap();let a=curve.mul(curve.gx,curve.gy,k1);let b=curve.mul(curve.gx,curve.gy,k2);let e=curve.add(a.0,a.1,b.0,b.1);let(_,_,_,regs)=analyze_ops(ops.iter());let mut empty=super::AuditWords{v:vec![],at:0};let mut init=Simulator::new(p.nq,p.nb,&mut empty);for(i,v)in[a.0,a.1,b.0,b.1].into_iter().enumerate(){init.set_register(&regs[i],v,0);}let mut expected=vec![false;p.nq];for(i,v)in[e.0,e.1].into_iter().enumerate(){for(bit,item)in regs[i].iter().enumerate(){match item{QubitOrBit::Qubit(q)=>expected[q.0 as usize]=v.bit(bit),_=>panic!("Quantum outputs")}}}let q=init.qubits.clone();let bits=init.bits.clone();drop(init);let started=std::time::Instant::now();let(aig,result)=match construct(p,&q,&bits){Ok(v)=>v,Err(at)=>return serde_json::json!({"status":"INCONCLUSIVE_BOOLEAN_NODE_BUDGET","at":at,"nonce_screens":0})};let build_seconds=started.elapsed().as_secs_f64();let mut noise=0xa8d7135f23649b01u64;for pattern in 0..3{let words:Vec<_>=(0..p.rng).map(|_|if pattern==0{0}else if pattern==1{u64::MAX}else{noise=noise.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);noise}).collect();let values=aig.evaluate(&words);let mut rng=super::AuditWords{v:words.iter().flat_map(|v|v.to_le_bytes()).collect(),at:0};let mut sim=Simulator::new(p.nq,p.nb,&mut rng);sim.qubits.copy_from_slice(&q);sim.bits.copy_from_slice(&bits);sim.apply_iter(ops.iter());for &q in outputs{assert_eq!(literal_value(result[q],&values),sim.qubits[q]&1!=0,"SourceAIG/protected mismatch pattern{pattern} output{q}");}drop(sim);assert_eq!(rng.at,p.rng*8);}
 let values:Vec<_>=outputs.iter().map(|&q|result[q]).collect();let expected:Vec<_>=outputs.iter().map(|&q|expected[q]).collect();let constant_wrong=values.iter().zip(&expected).filter(|(v,e)|**v<=1&&(**v==1)!=**e).count();let(text,variables,clauses)=cnf(&aig,&values,&expected);std::fs::write("wrongpoint.cnf",text).unwrap();serde_json::json!({"status":"EXACT_FIXED_SOURCE_INPUT_BOOLEAN_CNF_EXPORTED_NOT_YET_SOLVED","fixture":fixture,"Boolean_nodes":aig.nodes.len(),"cnf_variables":variables,"cnf_clauses":clauses,"constant_wrong_bits":constant_wrong,"build_seconds":build_seconds,"protected_fullstream_comparisons":3,"nonce_screens":0,"scope":"CNF is exact frozen source value model on one preserved failing input, with all original RNG bits existential. SAT means inconclusive; UNSAT would certify wrong point on this input only. No sampling-based rejection, no nonce selected/rejected or gate rerun."})}
#[cfg(test)]mod tests{use super::*;
 #[test]fn Boolean_dag_and_cnf_encodings_cover_all_three_variable_assignments(){let mut a=Aig::default();let x=a.node(0,0,0);let y=a.node(0,1,0);let z=a.node(0,2,0);let xy=a.and(x,y);let xy_x=a.xor(xy,x);let mux=a.ite(z,xy_x,y);for assignment in 0..8{let random:Vec<_>=(0..3).map(|i|((assignment>>i)&1)as u64).collect();let values=a.evaluate(&random);let x=assignment&1!=0;let y=assignment&2!=0;let z=assignment&4!=0;assert_eq!(literal_value(mux,&values),if z{(x&y)^x}else{y});}let(text,vars,clauses)=cnf(&a,&[mux],&[true]);assert!(text.starts_with(&format!("p cnf {vars} {clauses}\n")));assert!(vars>0&&clauses>0);}
 #[test]fn Boolean_cancellation_never_assumes_a_random_atom_constant(){let mut a=Aig::default();let x=a.node(0,0,0);let y=a.node(0,1,0);let xy=a.and(x,y);assert_eq!(a.and(xy,x),xy);assert_eq!(a.and(xy,x^1),0);assert_eq!(a.xor(x,x),0);let sum=a.xor(x,y);assert_eq!(a.xor(sum,x),y);assert_eq!(a.xor(sum,x^1),y^1);assert!(x>1);}
}

#[cfg(test)]mod cnf_exhaustive_tests{use super::*;
 #[test]fn actual_emitted_signed_cnf_equals_full_dag_truth_table(){let mut aig=Aig::default();let x=aig.node(0,0,0);let y=aig.node(0,1,0);let z=aig.node(0,2,0);let xy=aig.and(x^1,y);let xor=aig.xor(xy,z^1);let root=aig.ite(y,xor,x);for output in[0,1,xy,xor,root,root^1]{for expected in[false,true]{let(text,vars,_)=cnf(&aig,&[output],&[expected]);assert!(vars<16);let clauses:Vec<Vec<i64>>=text.lines().skip(1).map(|l|l.split_whitespace().map(|v|v.parse::<i64>().unwrap()).take_while(|&v|v!=0).collect()).collect();let mut live=vec![false;aig.nodes.len()];let mut stack=vec![output];while let Some(v)=stack.pop(){if v<=1{continue;}let i=(v/2-1)as usize;if live[i]{continue;}live[i]=true;let(k,a,b)=aig.nodes[i];if k!=0{stack.push(a);stack.push(b);}}let mut map=vec![None;aig.nodes.len()];let mut at=0;for(i,&yes)in live.iter().enumerate(){if yes{map[i]=Some(at);at+=1;}}assert_eq!(at,vars);for assignment in 0..(1usize<<vars){let mut random=vec![0;3];for(i,&(k,r,_))in aig.nodes.iter().enumerate(){if k==0{if let Some(bit)=map[i]{random[r as usize]=((assignment>>bit)&1)as u64;}}}let actual=aig.evaluate(&random);let consistent=map.iter().enumerate().all(|(i,b)|b.map(|bit|((assignment>>bit)&1!=0)==actual[i]).unwrap_or(true));let semantically=consistent&&literal_value(output,&actual)==expected;let encoded=clauses.iter().all(|c|c.iter().any(|&v|{let value=(assignment>>((v.unsigned_abs()-1)as usize))&1!=0;if v>0{value}else{!value}}));assert_eq!(encoded,semantically,"output{output} expected{expected} assignment{assignment}");}}}}
}
